          "claim": "rate's k8s.deployment.available is 0 for the whole abnormal window, from about 10:27:55; it is 1 in normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, time, value FROM abnormal_metrics WHERE attr_k8s_pod_name = 'rate-66f986cc46-sd6x7' AND metric='k8s.container.restarts' ORDER BY time",
          "claim": "The rate pod's restart counter climbs from 2 to 6 during the incident, showing a crash loop."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, quantile_cont(duration/1e6,0.5) p50ms FROM abnormal_traces WHERE service_name='rate' OR span_name LIKE 'rate.Rate/%' GROUP BY 1,2,3,4",
          "claim": "rate emits almost no spans in the abnormal window; in normal it had 529 rate.Rate/GetRates spans."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, quantile_cont(duration/1e6,0.5) p50ms FROM abnormal_traces WHERE service_name='search' GROUP BY 1,2,3,4 ORDER BY n DESC",
          "claim": "search's client calls to rate.Rate/GetRates return Error in about 14 µs (1006 of 1014), and search.Search/Nearby errors on the same requests."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name='search' AND level='ERROR' GROUP BY 1,2,3",
          "claim": "search logs 'Failed to get rates from rate service' 327 times during the incident."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code sc, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2,3,4,5",
          "claim": "All 741 frontend HTTP /hotels server spans return 500 with Error, matching the failed search.Search/Nearby calls."
        }
      ]
    }
  ]
}
